use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-wnaf-screen176";
mod split{include!("split.rs");pub fn apply(s:[u64;4])->[u64;4]{phi_split(s)}}
fn read(p:&str)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn naf(m:u128)->[i16;127]{assert!(m<1<<126);let mut out=[0i16;127];let mut k=m as i128;let mut pos=0;while k!=0{assert!(pos<127);if k&1!=0{let d=(k&4095)as i16;let d=if d>=2048{d-4096}else{d};out[pos]=d;k-=i128::from(d);}k/=2;pos+=1;}out}
fn balanced(m:u128)->[i16;11]{let mut out=[0;11];let mut k=m as i128;for d in&mut out{let low=(k&4095)as i16;*d=if low>=2048{low-4096}else{low};k=(k-i128::from(*d))/4096;}assert_eq!(k,0);out}
fn reconstruct(digits:&[i16],radix:i128)->i128{digits.iter().rev().fold(0i128,|a,&d|a.checked_mul(radix).unwrap().checked_add(d as i128).unwrap())}
fn check(m:u128)->([i16;11],[i16;127]){let b=balanced(m);let n=naf(m);assert_eq!(reconstruct(&b,4096),m as i128);assert_eq!(reconstruct(&n,2),m as i128);let mut last=None;for(i,&d)in n.iter().enumerate(){if d!=0{assert!(d.unsigned_abs()<2048&&d%2!=0);if let Some(previous)=last{assert!(i-previous>=12);}last=Some(i);}}(b,n)}
struct Model{rows:Vec<Vec<Vec<u32>>>,terms:Vec<u64>}
impl Model{fn new(windows:usize,buckets:usize)->Self{Self{rows:vec![vec![vec![0;buckets];2];windows],terms:vec![0;windows]}}fn add(&mut self,w:usize,p:usize,b:usize){self.rows[w][p][b]+=1;self.terms[w]+=1;}fn finish(&self)->Value{let mut summary=Vec::new();let mut arrivals=0u64;let mut assignments=0u64;let mut merges=0u64;let mut dense_fold=0u64;for(w,parts)in self.rows.iter().enumerate(){let occupied=parts.iter().map(|p|p.iter().filter(|&&n|n>0).count()as u64).collect::<Vec<_>>();let shared=(0..parts[0].len()).filter(|&b|parts[0][b]>0&&parts[1][b]>0).count()as u64;let max_slot=(0..parts[0].len()).rev().find(|&b|parts[0][b]>0||parts[1][b]>0).map(|b|b+1).unwrap_or(0);let fold=if max_slot>0{2*(max_slot as u64-1)}else{0};arrivals+=self.terms[w];assignments+=occupied.iter().sum::<u64>();merges+=shared;dense_fold+=fold;summary.push(json!({"position":w,"arrivals":self.terms[w],"occupied_per_part":occupied,"overlap_slots":shared,"dense_fold_slots":max_slot,"dense_fold_generic_model_adds":fold}));}assert!(arrivals>=assignments);json!({"positions":self.rows.len(),"arrivals":arrivals,"first_assignments":assignments,"post_first_arrivals":arrivals-assignments,"part_merges":merges,"dense_weighted_fold_model_adds":dense_fold,"generic_addition_model_total":arrivals-assignments+merges+dense_fold,"rows":summary})}}
fn main(){assert!(!std::path::Path::new(&format!("{R}/analysis.json")).exists());for(p,h)in read(&format!("{R}/pins.json")).as_object().unwrap(){assert_eq!(hash(&fs::read(p).unwrap()),h.as_str().unwrap());}let mut random=0x1234567812345678u128;let mut qualification=0;for i in 0..20000{random^=random<<23;random^=random>>17;random^=random<<26;let m=match i{0=>0,1=>1,2=>(1<<126)-1,3=>1<<125,4=>2047,5=>2048,6=>4095,7=>4096,_=>random&((1<<126)-1)};check(m);qualification+=1;}
let input=read(&format!("{R}/inputs.json"));let bytes=fs::read(input["fixture"]["fixture"].as_str().unwrap()).unwrap();assert_eq!(hash(&bytes),input["oracle"]["fixture_sha256"].as_str().unwrap());assert_eq!(&bytes[..8],b"B2SCAN01");let n=u64::from_le_bytes(bytes[8..16].try_into().unwrap())as usize;assert_eq!(bytes.len(),16+160*n);assert_eq!(n as u64,input["oracle"]["points"].as_u64().unwrap());let mut balanced_all=Model::new(11,2048);let mut balanced_ordinary=Model::new(10,2048);let mut wnaf=Model::new(127,1024);let chunk=n.div_ceil(2);let mut components=0u64;let mut skipped_identity=0;let mut top_terms=0;let mut canonical=0;let modulus=[4891460686036598785u64,2896914383306846353,13281191951274694749,3486998266802970665];
for i in 0..n{let point=&bytes[16+i*128..16+(i+1)*128];let scalar=&bytes[16+128*n+i*32..16+128*n+(i+1)*32];let words:[u64;4]=std::array::from_fn(|j|u64::from_le_bytes(scalar[j*8..j*8+8].try_into().unwrap()));assert!(words.iter().rev().cmp(modulus.iter().rev()).is_lt());canonical+=1;if point.iter().all(|&b|b==0){skipped_identity+=1;continue;}let short=split::apply(words);let part=usize::from(i>=chunk);for half in 0..2{let m=(short[2*half]as u128)|((short[2*half+1]&0x7fffffffffffffff)as u128)<<64;let(b,d)=check(m);components+=1;for(w,x)in b.into_iter().enumerate(){if x==0{continue;}let bucket=x.unsigned_abs()as usize-1;balanced_all.add(w,part,bucket);if w<10{balanced_ordinary.add(w,part,bucket);}else{top_terms+=1;}}for(w,x)in d.into_iter().enumerate(){if x!=0{wnaf.add(w,part,(x.unsigned_abs()as usize-1)/2);}}}}
let baseline=balanced_ordinary.finish();let candidate=wnaf.finish();let model_pass=candidate["generic_addition_model_total"].as_u64().unwrap()<baseline["generic_addition_model_total"].as_u64().unwrap();let mut out=BTreeMap::new();out.insert("complete",json!(true));out.insert("original_radix_all_including_indexed_top_hypothetical_dense",balanced_all.finish());out.insert("original_ordinary_excluding_indexed_top",baseline);out.insert("candidate_wnaf",candidate);out.insert("original_indexed_top_terms",json!(top_terms));out.insert("original_points",json!(n));out.insert("canonical_original_scalars_checked",json!(canonical));out.insert("identity_rows_skipped",json!(skipped_identity));out.insert("actual_components_reconstructed_each_recipe",json!(components));out.insert("additional_boundary_random_identity_cases",json!(qualification));out.insert("eager_generic_addition_model_selects_native",json!(model_pass));out.insert("limitations",json!(["Workmodel nottiming/lowerbound; cancellation/equalx/projectivequeue/SIMDtails/codec/inverse/scheduler costs omitted","Original ordinary comparison excludes accepted indexed top; candidate includes all positions; sameomission discloses asymmetry ratherthan disguising oldtop asdense","Candidate oddweighted fold also needs one per-position doubling and an extra all-bucket total; omitted gives candidate a favorable model","Root-only primary, no grouped2x2/all8/proof/resource qualification","Exact qualified decomposition inherited, no fresh complete curve oracle"]));out.insert("new_proofs",json!(0));out.insert("proof_ledger",json!(30708));out.insert("adopted",json!(false));out.insert("goal_achieved",json!(false));fs::write(format!("{R}/analysis.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Workscreen complete: originalordinary{},wnaf{},native_selected{model_pass};{components}actualcomponent identities/20000edge-random;no timing/proofs",out["original_ordinary_excluding_indexed_top"]["generic_addition_model_total"],out["candidate_wnaf"]["generic_addition_model_total"]);}
